import re


def eval_expression(expr):
    """
    +, -, *, / と括弧に対応した式の評価関数。
    負の数や単項の + / - も扱えます。
    """

    if not isinstance(expr, str):
        raise TypeError("expr must be a string")

    token_pattern = re.compile(
        r"\s*(?:(\d+(?:\.\d*)?|\.\d+)|([()+\-*/]))"
    )

    tokens = []
    pos = 0

    while pos < len(expr):
        match = token_pattern.match(expr, pos)

        if match is None:
            raise SyntaxError(f"不正な文字があります: {expr[pos]!r}")

        number, operator = match.groups()

        if number is not None:
            value = float(number)
            if value.is_integer() and "." not in number:
                value = int(value)
            tokens.append(("NUMBER", value))
        else:
            tokens.append((operator, operator))

        pos = match.end()

    tokens.append(("EOF", None))
    index = 0

    def current():
        return tokens[index]

    def consume(expected=None):
        nonlocal index

        token = current()
        if expected is not None and token[0] != expected:
            raise SyntaxError(
                f"{expected!r} が必要ですが、{token[0]!r} が見つかりました"
            )

        index += 1
        return token

    # 式: 加減算
    def parse_expression():
        value = parse_term()

        while current()[0] in ("+", "-"):
            operator = consume()[0]
            right = parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

        return value

    # 項: 乗除算
    def parse_term():
        value = parse_unary()

        while current()[0] in ("*", "/"):
            operator = consume()[0]
            right = parse_unary()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    # 単項演算子: -2, +3, --4 など
    def parse_unary():
        if current()[0] == "+":
            consume("+")
            return parse_unary()

        if current()[0] == "-":
            consume("-")
            return -parse_unary()

        return parse_primary()

    # 数値または括弧内の式
    def parse_primary():
        if current()[0] == "NUMBER":
            return consume("NUMBER")[1]

        if current()[0] == "(":
            consume("(")
            value = parse_expression()
            consume(")")
            return value

        raise SyntaxError(f"予期しないトークンです: {current()[1]!r}")

    result = parse_expression()

    if current()[0] != "EOF":
        raise SyntaxError(f"予期しないトークンです: {current()[1]!r}")

    return result
```

使用例:

```python
print(eval_expression("3 + 4 * (2 - 1)"))  # 7
print(eval_expression("-2 * 3 + 10"))      # 4
print(eval_expression("10 / (2 + 3)"))     # 2.0

eval_expression("1 / 0")  # ZeroDivisionError
```

`eval()` は使用せず、括弧・乗除算・加減算・負の数の優先順位を考慮して計算します。

